def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    giraffes = image_patch.find("giraffe")

    if not giraffes:
        return image_patch

    # Sort giraffes by their width (assuming width is a property we can check)
    giraffes.sort(key=lambda g: g.width, reverse=True)

    # Check which giraffe is facing the camera
    for giraffe in giraffes:
