def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    sheep_patches = image_patch.find("sheep")

    if len(sheep_patches) < 2:
        return image_patch

    standing_sheep = max(sheep_patches, key=lambda s: s.vertical_center)
    wooly_sheep = min([s for s in sheep_patches if s != standing_sheep], key=lambda s: s.vertical_center)

    wooly_sheep_horizontal_center = wooly_sheep.horizontal_center
    standing_sheep_horizontal_center = standing_sheep.horizontal_center

    if wooly_sheep_horizontal_center < standing_sheep_horizontal_center:
        return wooly_sheep
    else:
        return standing_sheep

modern_c2_ds.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    sheep_patches = image_patch.find("sheep")

    if not sheep_patches:
        return image_patch

    # Find the sheep that is sitting
    sitting_sheep = [s for s in sheep_patches if s.verify_property("sheep", "sitting")]
    if not sitting_sheep:
        return sheep_patches[0]

    # Find the standing sheep
    standing_sheep = [s for s in sheep_patches if s not in sitting_sheep]
    if not standing_sheep:
        return sitting_sheep[0]

    # Find the sheep that is sitting to one side of the standing sheep
    sitting_sheep.sort(key=lambda s: s.horizontal_center)
    standing_sheep.sort(key=lambda s: s.horizontal_center)

    for sitting in sitting_sheep:
        for standing in standing_sheep:
            if abs(sitting.horizontal_center - standing.horizontal_center) > 0:
                return sitting

    return sitting_sheep[0]

