    sofa_patches = image_patch.find("sofa")
    chair_patches = image_patch.find("chair")

    if not sofa_patches or not chair_patches:
        return image_patch

    # Filter sofas that are between two chairs
    between_chairs = []
    for sofa in sofa_patches:
        # Check if sofa is between two chairs
        between = False
        for chair in chair_patches:
            if is_between_3d(sofa, chair, chair):
                between = True
                break
        if between:
            between_chairs.append(sofa)

    if not between_chairs:
        return sofa_patches[0]

    # Sort by depth to get the one between two chairs and closest to the camera
    between_chairs.sort(key=lambda s: (s.compute_depth(), s.horizontal_center))
    return between_chairs[0]

